#define ZOBJ_BIG(name)                                                      \
const struct ObjectEventGraphicsInfo gObjectEventGraphicsInfo_##name = {    \
    .tileTag = TAG_NONE,                                                    \
    .paletteTag = OBJ_EVENT_PAL_##name,                                     \
    .reflectionPaletteTag = OBJ_EVENT_PAL_TAG_NONE,                         \
    .size = 256,                                                            \
    .width = 16,                                                            \
    .height = 32,                                                           \
    .paletteSlot = PALSLOT_NPC_SPECIAL,                                     \
    .shadowSize = SHADOW_SIZE_M,                                            \
    .inanimate = TRUE,                                                      \
    .compressed = FALSE,                                                    \
    .tracks = TRACKS_NONE,                                                  \
    .oam = &gObjectEventBaseOam_16x32,                                      \
    .subspriteTables = sOamTables_16x32,                                    \
    .anims = sAnimTable_Inanimate,                                          \
    .images = sPicTable_##name,                                             \
    .affineAnims = gDummySpriteAffineAnimTable,                             \
};

#define ZOBJ_SMALL(name)                                                    \
const struct ObjectEventGraphicsInfo gObjectEventGraphicsInfo_##name = {    \
    .tileTag = TAG_NONE,                                                    \
    .paletteTag = OBJ_EVENT_PAL_##name,                                     \
    .reflectionPaletteTag = OBJ_EVENT_PAL_TAG_NONE,                         \
    .size = 128,                                                            \
    .width = 16,                                                            \
    .height = 16,                                                           \
    .paletteSlot = PALSLOT_NPC_SPECIAL,                                     \
    .shadowSize = SHADOW_SIZE_NONE,                                         \
    .inanimate = TRUE,                                                      \
    .compressed = FALSE,                                                    \
    .tracks = TRACKS_NONE,                                                  \
    .oam = &gObjectEventBaseOam_16x16,                                      \
    .subspriteTables = sOamTables_16x16,                                    \
    .anims = sAnimTable_Inanimate,                                          \
    .images = sPicTable_##name,                                             \
    .affineAnims = gDummySpriteAffineAnimTable,                             \
};


#define PLAYER_OBJECT_BIKE(palette, picTable)   \
.tileTag = TAG_NONE,                            \
.paletteTag = palette,                          \
.reflectionPaletteTag = OBJ_EVENT_PAL_TAG_NONE, \
.size = 512,                                    \
.width = 32,                                    \
.height = 32,                                   \
.paletteSlot = PALSLOT_PLAYER,                  \
.shadowSize = SHADOW_SIZE_M,                    \
.inanimate = FALSE,                             \
.compressed = FALSE,                            \
.tracks = TRACKS_BIKE_TIRE,                     \
.oam = &gObjectEventBaseOam_32x32,              \
.subspriteTables = sOamTables_32x32,            \
.anims = sAnimTable_Bike,                       \
.images = picTable,                             \
.affineAnims = gDummySpriteAffineAnimTable,

#define PLAYER_OBJECT_SURF(palette, picTable)   \
.tileTag = TAG_NONE,                            \
.paletteTag = palette,                          \
.reflectionPaletteTag = OBJ_EVENT_PAL_TAG_NONE, \
.size = 512,                                    \
.width = 32,                                    \
.height = 32,                                   \
